catalog_script_client.script:
function onLoad() {
	console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFrom()" );

    function getParameterValue( name1, name2 ) {
        var url = top.location.href;
		console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFrom() - url = " + url );
        var value = new URLSearchParams(url).get(name1);
		console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFrom() - value = " + value );

        if (value) {
            return value;
        } else {
            var gUrl = new GlideURL();
			console.info( "Manage if on an Order Guide._refreshRunningFrom() - gUrl = " + gUrl );
            gUrl.setFromCurrent();
            value = gUrl.getParam(name2);
			console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFrom() - value = " + value );
            return value;
        }
    }

	var _refreshRunningFromCallBack = function( response ) {
		var answer = response.responseXML.documentElement.getAttribute( "answer" );
		console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - answer = " + answer );
		var result = JSON.parse( answer );

		if ( typeof result !== "undefined" && result.status.code == 0 ) {
			console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - Entity State -> " + result.runningFrom.entity.toString() );
			g_form.setValue( "entity_state", result.runningFrom.entity.toString() );
			g_form.setValue(  "running_from", result.runningFrom.type.toString() );

			if ( result.runningFrom.type.toString() == "order_guide" ) {
				// g_form.setReadOnly( "entity", true );
				// g_form.setReadOnly( "identity", true );

				console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - entity = " + result.runningFrom.entity.toString() );
				// console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - entity_source = " + result.runningFrom.entity_source.toString() );

				if ( result.runningFrom.entity.toString() == "existing" ) {
					if ( result.runningFrom.entity_source.toString() != "requested_for" ) {
						console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - Different existing" );
						console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - requested_for -> " + g_form.getValue( result.runningFrom.entity_source.toString() ) );
						g_form.setValue( "entity", g_form.getValue( result.runningFrom.entity_source.toString() ) );
						// g_form.setVisible( "entity", true );
						console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - Different existing Done" );
					}
				} else {
					g_form.clearValue( "entity" );
					g_form.clearValue( "identity" );
					g_form.setReadOnly( "entity", true );
					g_form.setReadOnly( "identity", true );
					g_form.clearMessages( "entity" );
					g_form.clearMessages( "identity" );
					g_form.setMandatory( "entity", false );
					g_form.setMandatory( "identity", false );
					g_form.setReadOnly( "requested_offering", false );
					g_form.clearMessages( "requested_offering" );
				}
			} else {
				g_form.setValue( "entity", g_user.userID.toString() );
			}
		}
		console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - Done" );
		console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFromCallBack() - Done requested_for = " + g_form.getValue( "entity" ) );
	};

	var orderGuideSysId = getParameterValue( "sys_id", "sysparm_guide" );
	console.info( "x_gamlp_idm_lc.Manage if on an Order Guide._refreshRunningFrom(): orderGuideSysId = " + orderGuideSysId );

	var ajax = new GlideAjax( 'x_1610537_rbh_cust.ManageIdentityOfferingsForBusinessServiceUIHelper' );
	ajax.addParam( 'sysparm_name', 'getRunningFrom' );
	ajax.addParam( 'sysparm_cat_item', orderGuideSysId );
	ajax.getXML( _refreshRunningFromCallBack );

}
